From 275d8b773f060b3e9631d7c361103b5b4d8be087 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 29 Oct 2026 15:42:47 +0100
Subject: [PATCH] applets/notifications: Don't show popups that don't fit on
 screen

positionPopups() hides popups past the part of the screen they may fill,
but each new popup was then made visible anyway, so a burst of them put
extra popups far above the stack; leave visibility to positionPopups().

BUG: 510647
---
 applets/notifications/global/Globals.qml | 2 +-
 1 file changed, 1 insertion(+), 1 deletion(-)

diff --git a/applets/notifications/global/Globals.qml b/applets/notifications/global/Globals.qml
index 8e8e56f88d..d8c7e03aed 100644
--- a/applets/notifications/global/Globals.qml
+++ b/applets/notifications/global/Globals.qml
@@ -714,8 +714,8 @@ QtObject {
             }
         }
         onObjectAdded: (index, object) => {
+            // This also shows the popup, unless there is no room left for it yet
             globals.positionPopups();
-            object.visible = true;
             globals.popupNotificationsModel.playSoundHint(globals.popupNotificationsModel.index(index, 0));
         }
         onObjectRemoved: (index, object) => {
